 #include <lvgl/lvgl.h>

+#include <nuttx/input/touchscreen.h>
+
 #define LAUNCHER_SCREEN_W     1080
 #define LAUNCHER_SCREEN_H     1920
@@
 #define UNLOCK_DRAG_DIST      240
 #define CANVAS_BUF_SIZE       (LAUNCHER_SCREEN_W * LAUNCHER_SCREEN_H * 2)
+#define TOUCH_DEVPATH         "/dev/input0"
+#define TOUCH_RELEASE_MS      100
@@
 static volatile uint32_t g_refr_count;
 static uint32_t g_fps;
+
+static int g_touch_fd = -1;
+static lv_indev_state_t g_touch_state = LV_INDEV_STATE_RELEASED;
+static lv_point_t g_touch_point;
+static uint64_t g_touch_last_down_ms;
@@
 static uint32_t launcher_uptime_sec(void)
 {
@@
   return (uint32_t)ts.tv_sec;
 }
+
+static uint64_t launcher_uptime_ms(void)
+{
+  struct timespec ts;
+
+  clock_gettime(CLOCK_MONOTONIC, &ts);
+  return (uint64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
+}
+
+static void launcher_touch_read_cb(lv_indev_t *indev,
+                                   lv_indev_data_t *data)
+{
+  struct touch_sample_s sample;
+  uint64_t now = launcher_uptime_ms();
+  ssize_t nread;
+
+  UNUSED(indev);
+
+  nread = read(g_touch_fd, &sample, sizeof(sample));
+  if (nread == sizeof(sample) && sample.npoints > 0 &&
+      (sample.point[0].flags & (TOUCH_DOWN | TOUCH_MOVE)) != 0)
+    {
+      g_touch_point.x = sample.point[0].x;
+      g_touch_point.y = sample.point[0].y;
+      g_touch_last_down_ms = now;
+      g_touch_state = LV_INDEV_STATE_PRESSED;
+    }
+
+  /* GT9XX synthesizes TOUCH_UP on the read immediately after every DOWN.
+   * Keep the contact pressed while fresh DOWN reports are still arriving.
+   */
+
+  if (g_touch_state == LV_INDEV_STATE_PRESSED &&
+      now - g_touch_last_down_ms >= TOUCH_RELEASE_MS)
+    {
+      g_touch_state = LV_INDEV_STATE_RELEASED;
+    }
+
+  data->point = g_touch_point;
+  data->state = g_touch_state;
+}
+
+static lv_indev_t *launcher_touch_create(void)
+{
+  lv_indev_t *indev;
+
+  g_touch_fd = open(TOUCH_DEVPATH, O_RDONLY | O_NONBLOCK | O_CLOEXEC);
+  if (g_touch_fd < 0)
+    {
+      fprintf(stderr, "launcher: cannot open %s: %d\n",
+              TOUCH_DEVPATH, errno);
+      return NULL;
+    }
+
+  indev = lv_indev_create();
+  if (indev == NULL)
+    {
+      close(g_touch_fd);
+      g_touch_fd = -1;
+      return NULL;
+    }
+
+  lv_indev_set_type(indev, LV_INDEV_TYPE_POINTER);
+  lv_indev_set_read_cb(indev, launcher_touch_read_cb);
+  return indev;
+}
@@
